pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 warp) public {
        vm.assume(warp > 0);
        vm.warp(warp);
        vm.deal(address(this), 20 ether);
        (bool success, ) = address(c).call{value: amount}("");
        bool isPastBlockTimeSet = amount == 10 ether;
        uint256 actualPastBlockTime = c.pastBlockTime();
        if (isPastBlockTimeSet) {
            assertTrue(actualPastBlockTime == warp);
        } else {
            assertTrue(actualPastBlockTime == 0);
        }
    }
}
